@sig trait Resource_Observation_Api {
  def id: Art.BridgeId
  def cargo_band_Id : Art.PortId
  def capacitor_band_Id : Art.PortId
  def location_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var cargo_band: Mining_Threat_Retreat_Supervision.CargoBandValue = $

  def put_cargo_band(value : Mining_Threat_Retreat_Supervision.CargoBandValue) : Unit = {
    Contract(
      Modifies(cargo_band),
      Ensures(
        cargo_band == value
      )
    )
    Spec {
      cargo_band = value
    }

    Art.putValue(cargo_band_Id, Mining_Threat_Retreat_Supervision.CargoBandValue_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var capacitor_band: Mining_Threat_Retreat_Supervision.CapacitorBandValue = $

  def put_capacitor_band(value : Mining_Threat_Retreat_Supervision.CapacitorBandValue) : Unit = {
    Contract(
      Modifies(capacitor_band),
      Ensures(
        capacitor_band == value
      )
    )
    Spec {
      capacitor_band = value
    }

    Art.putValue(capacitor_band_Id, Mining_Threat_Retreat_Supervision.CapacitorBandValue_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var location: Mining_Threat_Retreat_Supervision.LocationValue = $

  def put_location(value : Mining_Threat_Retreat_Supervision.LocationValue) : Unit = {
    Contract(
      Modifies(location),
      Ensures(
        location == value
      )
    )
    Spec {
      location = value
    }

    Art.putValue(location_Id, Mining_Threat_Retreat_Supervision.LocationValue_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Resource_Observation_Initialization_Api (
  val id: Art.BridgeId,
  val cargo_band_Id : Art.PortId,
  val capacitor_band_Id : Art.PortId,
  val location_Id : Art.PortId) extends Resource_Observation_Api

@datatype class Resource_Observation_Operational_Api (
